// Golden values of the Projects map geometry (docs/spec/03 §3, 02 SCR-WORLDMAP-FRAME). worldmap.golden.json was
// generated by scripts/proto-golden-worldmap.ts: the prototype map page's own functions (projected, clusters,
// styleOf, tagClass, fitBox, applyView, boxOf, homeView, onClick, focusCode, placeTip), extracted verbatim and run
// against d3-geo, for every zone, three frame sizes and seven zoom levels. The domain functions must reproduce them
// with the same projection (NaturalEarth1 fitted to the sphere with a 6 px inset).
import { geoNaturalEarth1 } from 'd3-geo';
import { describe, expect, it } from 'vitest';
import type { Health } from './health';
import { STAGES, stage } from '@/server/db/codes';
import screenGolden from '@/features/worldmap/worldmap.golden.json';
import {
  clusterClick, clusterKey, clusterPoints, defaultView, focusTransform, homeView, mapCategoryOf, mapCrumbExtra, mapKpis, markerLabel,
  markerStyleOf, placeTooltip, showMarkerLabels, tooltipHeader, viewTransform, type GeoBounds, type MapCategory,
  type Placed, type Projector,
} from './worldmap';
import golden from './worldmap.golden.json';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const HEALTH: Record<string, Health | null> = { 'On track': 'on_track', 'At risk': 'at_risk', 'Off track': 'off_track', '': null };
const ZONES = ['null', 'euna', 'afr', 'apac'];

function frame(W: number, H: number) {
  const proj = geoNaturalEarth1().fitExtent([[6, 6], [W - 6, H - 6]], { type: 'Sphere' });
  const project: Projector = (p) => proj(p);
  return project;
}

const placedOf = (zone: string, project: Projector): (Placed & { city: string })[] =>
  G.zones[zone].points.map((p: any) => {
    const [x, y] = project([p.lng, p.lat])!;
    return { code: p.code, city: p.city, x, y };
  });

describe('worldmap — projection, clusters and framing match the prototype map page', () => {
  for (const zone of ZONES)
    for (const [W, H] of G.sizes as [number, number][]) {
      const g = G.geometry[`${zone}|${W}x${H}`];
      it(`zone ${zone} · ${W}×${H}`, () => {
        const project = frame(W, H);
        const pts = placedOf(zone, project);
        expect(pts.map(({ code, x, y }) => ({ code, x, y }))).toEqual(g.projected);

        const z = G.zones[zone];
        expect(homeView(!!z.zone, z.points)).toBe(g.homeView);
        const f = { W, H, project, zoneBounds: (z.zone?.bounds ?? null) as GeoBounds | null, points: pts };
        expect({ world: viewTransform('world', f), europe: viewTransform('europe', f), fit: viewTransform('fit', f) }).toEqual(g.views);

        for (const k of G.ks as number[]) {
          const cl = clusterPoints(pts, k);
          expect(cl.map((c) => ({ codes: c.items.map((i) => i.code), x: c.x, y: c.y })), `k=${k}`).toEqual(g.clusters[k]);
          expect(cl.map((c) => {
            const r = clusterClick(c, W, H);
            return r.kind === 'zoom' ? { zoom: r.transform } : { pin: c.items.map((i) => i.code) };
          }), `click k=${k}`).toEqual(g.clicks[k]);
        }
        expect(Object.fromEntries(pts.map((p) => [p.code, focusTransform(p.code, pts, W, H)]))).toEqual(g.focus);
      });
    }

  it('marker styles follow category and health codes (styleOf)', () => {
    // L-7 (R-135): the prototype's tooltip status tag (`tagClass`, from category and health) is not kept: the tooltip's
    // stage tag takes the stage colour like the side list — asserted in src/features/worldmap/render.test.ts.
    for (const p of G.zones.null.points) {
      const health = HEALTH[p.health];
      expect(markerStyleOf(p.cat as MapCategory, health), p.code).toBe(G.styles[p.code].style);
    }
    // Codes, not labels: the French render of the prototype compared "Conforme" with "On track" (00 §7.16).
    expect(markerStyleOf('active', 'on_track')).toBe('ontrack');
    // The grey marker ("Closed / cancelled") also covers an execution project without a health yet ('other').
    expect(markerStyleOf('other', null)).toBe('closed');
  });

  it('map category from the stage code and the health (mapPts.cat, logic 5074)', () => {
    // The prototype's own categories for the 17 seeded projects (status label → stage code).
    for (const p of (screenGolden as any)['en|null'].points)
      expect(mapCategoryOf(stage.code(p.status), HEALTH[p.health]), p.code).toBe(p.cat);
    // Every stage: pipeline and terminal stages ignore the health; others are active with a health, else "other".
    for (const s of STAGES) {
      const expected = ['initiative', 'aps', 'apd'].includes(s.code) ? 'pipeline' : ['clos', 'annule'].includes(s.code) ? 'closed' : null;
      expect(mapCategoryOf(s.code, 'off_track'), s.code).toBe(expected ?? 'active');
      expect(mapCategoryOf(s.code, null), s.code).toBe(expected ?? 'other');
    }
    expect(markerStyleOf(mapCategoryOf('etudes', null), null)).toBe('closed');
  });

  it('tooltip placement (placeTip)', () => {
    for (const p of G.placements) {
      const sx = p.t.k * p.d.x + p.t.x;
      const sy = p.t.k * p.d.y + p.t.y;
      const { x, y } = placeTooltip(sx, sy, p.tw, p.th, 800, 500);
      expect({ left: `${x}px`, top: `${y}px` }).toEqual(p.out);
    }
  });

  it('labels, keys, default view and helpers', () => {
    expect(showMarkerLabels(1, 7)).toBe(false);
    expect(showMarkerLabels(1, 4)).toBe(true);
    expect(showMarkerLabels(2.4, 11)).toBe(true);
    expect(clusterKey({ items: [{ code: 'RCF-019' }, { code: 'HLT-026' }] })).toBe('HLT-026|RCF-019');
    expect(markerLabel([{ city: 'Lyon' }, { city: 'Lyon' }])).toEqual({ city: 'Lyon', sites: 1 });
    expect(markerLabel([{ city: 'Lyon' }, { city: 'Le Havre' }])).toEqual({ city: null, sites: 2 });
    expect(tooltipHeader([{ city: 'Le Havre', country: 'France' }, { city: 'Le Havre', country: 'France' }])).toEqual({ place: 'Le Havre · France', sites: 1, projects: 2 });
    expect(tooltipHeader([{ city: 'Lyon', country: 'France' }, { city: 'Casablanca', country: 'Morocco' }])).toEqual({ place: null, sites: 2, projects: 2 });
    expect(defaultView([])).toBe('world');
    expect(defaultView([{ lat: 49.49, lng: 0.11 }, { lat: 43.3, lng: 5.37 }])).toBe('fit');
    expect(homeView(true, [])).toBe('europe');
    const project = frame(800, 500);
    expect(viewTransform('fit', { W: 800, H: 500, project, zoneBounds: null, points: [] })).toEqual({ k: 1, x: 0, y: 0 });
    expect(focusTransform('XXX-000', [], 800, 500)).toBeNull();
  });
});

describe('worldmap — host KPI tiles (mapKpis, logic 5080)', () => {
  const kpiInput = (zone: string) =>
    G.zones[zone].points.map((p: any) => ({ category: p.cat, health: HEALTH[p.health], site: `${p.city}|${p.country}`, country: p.country }));
  const expected: Record<string, [string, string][]> = {
    null: [['17', 'Whole portfolio'], ['11', '6 countries'], ['7', '5 in pipeline'], ['3', '1 off track']],
    euna: [['11', 'Europe & North America'], ['5', '2 countries'], ['6', '1 in pipeline'], ['3', '1 off track']],
    afr: [['3', 'Africa'], ['3', '2 countries'], ['1', '1 in pipeline'], ['0', '0 off track']],
    apac: [['3', 'Asia Pacific'], ['3', '2 countries'], ['0', '3 in pipeline'], ['0', '0 off track']],
  };
  it.each(ZONES)('zone %s', (zone) => {
    const z = G.zones[zone];
    const k = mapKpis(kpiInput(zone), 0, z.zone?.label ?? null);
    expect(k.map((x) => [x.value, x.sub])).toEqual(expected[zone]);
    expect(k.map((x) => x.label)).toEqual(['Projects located', 'Sites', 'Active on site', 'At risk']);
    expect(k[3].alert).toBe(zone === 'null' || zone === 'euna');
  });
  it('without location and singular country', () => {
    const k = mapKpis([{ category: 'pipeline', health: null, site: 'Lyon|France', country: 'France' }], 2, 'Africa');
    expect(k.map((x) => x.sub)).toEqual(['2 without location', '1 country', '1 in pipeline', '0 off track']);
    expect(mapCrumbExtra(17, null)).toBe('17 projects located');
    expect(mapCrumbExtra(3, 'Africa')).toBe('3 projects located · Africa');
    expect(mapCrumbExtra(1, null)).toBe('1 project located');
  });
});
